.card { --readest-ink: #172033; --readest-muted: #5b667a; --readest-line: #d9e0ea; --readest-recognition: #2563eb; --readest-recognition-soft: #dbeafe; --readest-production: #15803d; --readest-production-soft: #dcfce7; background: #ffffff; color: var(--readest-ink); font-family: sans-serif; font-size: 21px; text-align: start; line-height: 1.45; padding: 18px; } .readest-card-header { margin-bottom: 16px; } .readest-card-badge { display: inline-block; padding: 4px 10px; border: 1px solid var(--readest-recognition); border-radius: 999px; color: var(--readest-recognition); background: var(--readest-recognition-soft); font-size: 0.68em; font-weight: 700; letter-spacing: 0.08em; line-height: 1.2; text-transform: uppercase; } .readest-card-badge-production { border-color: var(--readest-production); color: var(--readest-production); background: var(--readest-production-soft); } .readest-context { font-size: 1.08em; line-height: 1.55; } .readest-target { padding: 1px 4px; border-radius: 4px; color: var(--readest-recognition); background: var(--readest-recognition-soft); font-weight: 700; text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 3px; } .readest-prompt { padding: 12px 14px; border-left: 4px solid var(--readest-production); border-radius: 4px; background: var(--readest-production-soft); font-size: 1.08em; font-weight: 600; } .readest-production-gloss { margin-top: 12px; color: var(--readest-muted); font-size: 0.9em; } .readest-hint { margin-top: 14px; padding: 10px 12px; border-left: 3px solid var(--readest-muted); color: var(--readest-muted); font-size: 0.9em; } .readest-divider { margin: 20px 0 16px; border-top: 2px solid var(--readest-line); } .readest-section { margin: 12px 0; } .readest-label { margin-bottom: 3px; color: var(--readest-muted); font-size: 0.65em; font-weight: 700; letter-spacing: 0.08em; line-height: 1.2; text-transform: uppercase; } .readest-answer { color: var(--readest-production); font-size: 1.2em; font-weight: 700; } .readest-meta { display: flex; flex-wrap: wrap; gap: 6px 12px; margin: 14px 0; color: var(--readest-muted); font-size: 0.82em; } .readest-meta span + span { padding-left: 12px; border-left: 1px solid var(--readest-line); } .readest-details { margin-top: 16px; color: var(--readest-muted); font-size: 0.82em; } .readest-details summary { color: var(--readest-ink); font-weight: 700; cursor: pointer; } .readest-source-meta { margin: 8px 0; } @media (prefers-color-scheme: dark) { .card { --readest-ink: #edf2f7; --readest-muted: #aab5c5; --readest-line: #3a4658; --readest-recognition-soft: #172554; --readest-production-soft: #14351f; background: #111827; } }
[hidden] { display: none !important; }
.context-origin { margin-top: 8px; font-size: 0.75em; opacity: 0.65; }

