{{#EnableRecognition}}<div class='readest-card readest-recognition' data-direction='recognition' data-reveal='false'><div class='readest-card-header'><span class='readest-card-badge'>Recognition</span></div><div class='random-sentence readest-context'><span class='context-before'>{{SentenceBefore}}</span><mark class='context-target readest-target'>{{SelectedText}}</mark><span class='context-after'>{{SentenceAfter}}</span></div><div class='context-origin readest-meta'>Original context</div><div hidden><span class='primary-before'>{{SentenceBefore}}</span><span class='primary-target'>{{SelectedText}}</span><span class='primary-after'>{{SentenceAfter}}</span><div class="context-data">{{UsageNote}}</div></div><script>(function(){
 var root=document.currentScript.parentElement;
 try {
  var production=root.dataset.direction==='production',reveal=root.dataset.reveal==='true';
  var primary={before:root.querySelector('.primary-before').textContent,target:root.querySelector('.primary-target').textContent,after:root.querySelector('.primary-after').textContent,original:true};
  var payload=JSON.parse(root.querySelector('.context-json').textContent);
  var variants=payload[production?'production':'recognition'];
  var contexts=[primary].concat(variants);
  var key='readest-contexts-v1:'+payload.key+':'+root.dataset.direction;
  var signature=JSON.stringify(contexts),saved=null,storage=null;
  var memory=window.__readestContextSelections||(window.__readestContextSelections={});
  var candidates=[function(){return window.localStorage;},function(){return window.sessionStorage;}];
  for(var i=0;i<candidates.length;i++){try{var candidate=candidates[i](),probe=key+':probe';candidate.setItem(probe,'1');candidate.removeItem(probe);storage=candidate;break;}catch(ignored){}}
  if(storage){try{saved=JSON.parse(storage.getItem(key));}catch(ignored){}}
  if(!saved){saved=memory[key]||null;}
  var previous=saved&&saved.signature===signature&&saved.index>=0&&saved.index<contexts.length?saved.index:null;
  var index=previous===null?0:previous;
  if(!reveal){index=previous===null?Math.floor(Math.random()*contexts.length):(previous+1+Math.floor(Math.random()*(contexts.length-1)))%contexts.length;memory[key]={signature:signature,index:index};if(storage){try{storage.setItem(key,JSON.stringify(memory[key]));}catch(ignored){}}}
  var selected=contexts[index];
  var sentence=root.querySelector('.random-sentence'),original=root.querySelector('.original-prompt');
  if(production&&selected.original){
   sentence.hidden=true;original.hidden=false;
   if(reveal){original.innerHTML=original.innerHTML.replace(/\[\.\.\.\]|\[…\]|___+/g,function(){return root.querySelector('.primary-target').innerHTML;});}
  }else{
   if(original){original.hidden=true;}sentence.hidden=false;
   root.querySelector('.context-before').textContent=selected.before;
   root.querySelector('.context-target').textContent=production&&!reveal?'['+payload.cue+']':selected.target;
   root.querySelector('.context-after').textContent=selected.after;
  }
  root.querySelector('.context-origin').textContent=selected.original?'Original context':'Additional example';
  var answer=root.querySelector('.selected-answer');if(answer&&production){answer.textContent=selected.target;}
 }catch(ignored){/* Original fields are a usable fallback. */}
})();</script></div>{{/EnableRecognition}}

